content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-sub: #64748b;
  --border-color: #e2e8f0;
  --shibuya-color: #3b82f6;
  --shinjuku-color: #ec4899;
  --ikebukuro-color: #10b981;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1000px;
  margin: 2rem auto;
  padding: 1.5rem;
  background-color: var(--card-bg);
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.header {
  margin-bottom: 1.5rem;
  text-align: center;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.5rem;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-sub);
}

.control-panel {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.5rem;
  padding: 1rem;
  background-color: var(--bg-color);
  border-radius: 8px;
  border: 1px solid var(--border-color);
}

@media (min-width: 640px) {
  .control-panel {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.toggle-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.store-btn {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  border: 1px solid var(--border-color);
  background-color: var(--card-bg);
  color: var(--text-sub);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.store-btn:hover {
  background-color: var(--border-color);
}

.store-btn.active {
  background-color: var(--primary-color);
  color: #ffffff;
  border-color: var(--primary-color);
}

.chart-wrapper {
  width: 100%;
  height: 400px;
  margin-bottom: 2rem;
}

.table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

.data-table th,
.data-table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
}

.data-table th {
  background-color: var(--bg-color);
  font-weight: 600;
  color: var(--text-main);
}

.data-table tr:hover {
  background-color: var(--bg-color);
}

export interface MonthlyData {
  month: string;
  渋谷店: number;
  新宿店: number;
  池袋店: number;
}

import { useState } from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { MonthlyData } from './types';
import './index.css';

const initialData: MonthlyData[] = [
  { month: '1月', 渋谷店: 1200, 新宿店: 1500, 池袋店: 1100 },
  { month: '2月', 渋谷店: 1350, 新宿店: 1600, 池袋店: 1250 },
  { month: '3月', 渋谷店: 1500, 新宿店: 1800, 池袋店: 1400 },
  { month: '4月', 渋谷店: 1400, 新宿店: 1700, 池袋店: 1300 },
  { month: '5月', 渋谷店: 1600, 新宿店: 1900, 池袋店: 1550 },
  { month: '6月', 渋谷店: 1550, 新宿店: 1850, 池袋店: 1500 },
  { month: '7月', 渋谷店: 1700, 新宿店: 2100, 池袋店: 1650 },
  { month: '8月', 渋谷店: 1850, 新宿店: 2300, 池袋店: 1800 },
  { month: '9月', 渋谷店: 1650, 新宿店: 1950, 池袋店: 1600 },
  { month: '10月', 渋谷店: 1500, 新宿店: 1800, 池袋店: 1450 },
  { month: '11月', 渋谷店: 1600, 新宿店: 1900, 池袋店: 1550 },
  { month: '12月', 渋谷店: 1900, 新宿店: 2400, 池袋店: 1950 },
];

export default function App() {
  const [visibleStores, setVisibleStores] = useState<{
    渋谷店: boolean;
    新宿店: boolean;
    池袋店: boolean;
  }>({
    渋谷店: true,
    新宿店: true,
    池袋店: true,
  });

  const toggleStore = (store: '渋谷店' | '新宿店' | '池袋店') => {
    setVisibleStores((prev) => ({
      ...prev,
      [store]: !prev[store],
    }));
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">店舗別月別来客数比較</h1>
        <p className="subtitle">渋谷店・新宿店・池袋店の月ごとの来客数をグラフと表で確認できます。</p>
      </header>

      <div className="control-panel">
        <div className="toggle-group">
          <button
            className={`store-btn ${visibleStores.渋谷店 ? 'active' : ''}`}
            onClick={() => toggleStore('渋谷店')}
          >
            渋谷店
          </button>
          <button
            className={`store-btn ${visibleStores.新宿店 ? 'active' : ''}`}
            onClick={() => toggleStore('新宿店')}
          >
            新宿店
          </button>
          <button
            className={`store-btn ${visibleStores.池袋店 ? 'active' : ''}`}
            onClick={() => toggleStore('池袋店')}
          >
            池袋店
          </button>
        </div>
      </div>

      <div className="chart-wrapper">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={initialData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
            <XAxis dataKey="month" stroke="#64748b" />
            <YAxis stroke="#64748b" />
            <Tooltip />
            <Legend />
            {visibleStores.渋谷店 && (
              <Line
                type="monotone"
                dataKey="渋谷店"
                stroke="#3b82f6"
                strokeWidth={2}
                activeDot={{ r: 8 }}
              />
            )}
            {visibleStores.新宿店 && (
              <Line
                type="monotone"
                dataKey="新宿店"
                stroke="#ec4899"
                strokeWidth={2}
                activeDot={{ r: 8 }}
              />
            )}
            {visibleStores.池袋店 && (
              <Line
                type="monotone"
                dataKey="池袋店"
                stroke="#10b981"
                strokeWidth={2}
                activeDot={{ r: 8 }}
              />
            )}
          </LineChart>
        </ResponsiveContainer>
      </div>

      <div className="table-wrapper">
        <table className="data-table">
          <thead>
            <tr>
              <th>月</th>
              {visibleStores.渋谷店 && <th>渋谷店</th>}
              {visibleStores.新宿店 && <th>新宿店</th>}
              {visibleStores.池袋店 && <th>池袋店</th>}
            </tr>
          </thead>
          <tbody>
            {initialData.map((row) => (
              <tr key={row.month}>
                <td>{row.month}</td>
                {visibleStores.渋谷店 && <td>{row.渋谷店.toLocaleString()} 人</td>}
                {visibleStores.新宿店 && <td>{row.新宿店.toLocaleString()} 人</td>}
                {visibleStores.池袋店 && <td>{row.池袋店.toLocaleString()} 人</td>}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
